#!/usr/bin/env bash
# Rebuild netlify/functions/gpt.mjs from netlify/gpt-fn.src.mjs + gpt-core.mjs.
# Run after changing either source file, then commit the generated bundle.
set -euo pipefail
cd "$(dirname "$0")"
npm install --no-save --no-audit --no-fund --prefix . @netlify/blobs@8.2.0 >/dev/null
rm -f package.json package-lock.json
npx -y esbuild@0.24.2 gpt-fn.src.mjs --bundle --platform=node --format=esm --target=node20 \
  --banner:js="// GENERATED by netlify/build-gpt.sh from gpt-fn.src.mjs + gpt-core.mjs — edit those, not this.
import { createRequire as __createRequire } from 'node:module'; const require = __createRequire(import.meta.url);" \
  --outfile=functions/gpt.mjs
node --check functions/gpt.mjs
echo "built functions/gpt.mjs ($(wc -c < functions/gpt.mjs) bytes)"
